import React, { useState } from "react";
import CheckoutLine from "./checkout-line";
import ClipboardButton from "./icon-button";
import "./checkout-form.css";
import "./modal.css";
import * as jose from 'jose'


function Spinner({ size = 40, color = "#3b82f6" }) {
  const style = {
    width: size,
    margin: `auto`,
    height: size,
    border: `${size / 8}px solid #e5e7eb`,
    borderTop: `${size / 8}px solid ${color}`,
    borderRadius: "50%",
    animation: "spin 1s linear infinite",
  };

  return (
    <>
      <div style={style} />
      <style>
        {`
          @keyframes spin {
            to {
              transform: rotate(360deg);
            }
          }
        `}
      </style>
    </>
  );
}

export function CheckoutModal({image, title, description, quantity, price, currency, shipping, show}){
	return(
		<div id="modal" >
		<div id="modal-inner" style={{textAlign:`center`}} >

		<CheckoutTabs
		paymentComponent={ <><CheckoutLine
			image={ image }
			title={ title }
			description={ description }
			quantity={ quantity }
			price={ price }
			currency={ currency }
			shipping={ shipping }
			total={ price + shipping }
			/><CheckoutForm title={title} quantity={quantity} /></> }
		crypto1={ <Spinner size={150}/> } />

		<button type="button"
		onClick={ e=> show( false ) }
		className="close-button"
		target="_blank"
		rel="noopener noreferrer"
		style={{
			margin: "4px",
				display: "block",
				padding: "12px 20px",
				borderRadius: "6px",
				textDecoration: "none",
				fontWeight: "bold",
		}} >
		Back
		</button>

		</div>
		</div> );
}

export function CheckoutTabs({
	paymentComponent,
	crypto1,
	crypto2,
}) {
	const [active, setActive] = useState("payment");

	return (
		<div className="checkout">
		<div className="checkout-tabs">
		<button
		className={active === "payment" ? "active" : ""}
		onClick={() => setActive("payment")} >
		Checkout
		</button>
		<button
		className={active === "crypto1" ? "active" : ""}
		onClick={() => setActive("crypto1")} >
		Bank
		</button>
		</div>
		<div className="checkout-content">
		{active === "payment" && paymentComponent}
		{active === "crypto1" && crypto1}
		{active === "crypto2" && crypto2}
		</div>
		</div>
	);
}

