const ALG = "RSA-OAEP-256";

export function CheckoutForm({ title, quantity }){

	const [formData, setFormData] = useState({
		title: title,
		quantity: quantity,
		address: "",
		postcode: "",
		message: ""
	});

	const [serialised, setSerialized] = useState( null );

	async function encrypt( txt  ) {
		const _publicKey = await jose.importSPKI(  PUBLIC_KEY , ALG  )
		const jwe = await new jose.CompactEncrypt(
			new TextEncoder().encode( txt )
		)
			.setProtectedHeader({ alg: 'RSA-OAEP-256', enc: 'A256GCM' })
			.encrypt( _publicKey )

		setSerialized(jwe)

	}

	const handleChange = (e) => {
		const { name, value } = e.target;
		setFormData((prev) => ({ ...prev, [name]: value }));
	};

	const handleSubmit = (e) => {
		e.preventDefault();
		console.log("Form submitted:", formData);
	};

	const SerialData = ({text}) => {
		const [copied, setCopied] = useState(false);

		const copy = ({ text}) => {
			navigator.clipboard.writeText(text);
			setCopied(true);
			setTimeout(() => setCopied(false), 2000);
		};

		const emailAddr = "c.lacdael@live.co.uk";
		return(
			<>
			<span>Email the following to : <u><i>{emailAddr}</i></u><ClipboardButton text={emailAddr} /></span>
			<div
			style={{
				wordBreak: "break-all",
					cursor: "pointer",
					fontSize: "0.9rem",
					background: "#f6f6f6",
					padding: "0.7rem",
					borderRadius: "8px",
			}}
			onClick={copy}
			>
			{text}
			</div>
			<button type="button" onClick={ copy }
			className="submit-button">
			{copied ? "COPIED" : "📋COPY"}
			</button> &nbsp;
			<a
			href={`mailto:${ emailAddr }?subject=Order-Submit&body=${text}`} 
			className="submit-button"
			>
			📩E-mail
			</a></>
		);
	} 
const isDisabled =
  !formData.address.trim() || !formData.postcode.trim();
	return ( <>
		{ serialised ? <SerialData text={serialised} /> : <form
			className="checkout-form" onSubmit={handleSubmit}>
			<label>
			Address:
			<input
			type="text"
			name="address"
			value={formData.address}
			onChange={handleChange}
			required
			placeholder="Enter your address"
			/>
			</label>

			<label>
			Postcode:
			<input
			type="text"
			name="postcode"
			value={formData.postcode}
			onChange={handleChange}
			required
			placeholder="Enter postcode"
			/>
			</label>

			<label>
			Message:
			<textarea
			name="message"
			value={formData.message}
			onChange={handleChange}
			placeholder="Optional message"
			rows={4}
			/>
			</label>



<button
  type="submit"
  disabled={isDisabled}
  onClick={e => encrypt(JSON.stringify(formData))}
  className="submit-button"
>
  Submit
</button>

			</form> } </>
	);
}

